// === Tab: mySketch ===
let timer=0
const range=28

setup=()=> {
  createCanvas(windowWidth, windowHeight, WEBGL)
}

draw=()=> {
  background(0)
  directionalLight(color('white'), 0, -1, -1);
  let angle=timer++/120
  rotateX(angle)
  rotateZ(angle)
  scale(18)
  translate(-range/2, -range/2, -range/2)
  for (let z=range; z--; ) {
    for (let y=range; y--; ) {
      for (let x=range; x--; ) {
        if (x^y^z)continue; 
        push()
        translate(x, y, z)
        box(tan(x+timer/557), tan(y), tan(z+timer/787)) 
        pop()
      }
    }
  }
}
